// Download draws the screen in an area of w by h cells for the values in p.
func Download(p DownloadProps, w, h int) Frame {
	return drawScreen(downloadParts, p, p.Theme, w, h, downloadBackground, downloadEnv)
}

// DownloadSize is the size of area the screen was designed for.
func DownloadSize() (w, h int) { return downloadWidth, downloadHeight }

// DownloadLayout is the screen without its drawing: the frame has the regions of the
// visible components, so a program can size a model of its own before it is
// drawn into one of them.
func DownloadLayout(p DownloadProps, w, h int) Frame {
	return layoutScreen(downloadParts, p, p.Theme, w, h, downloadEnv)
}

// DownloadHandle turns a click or a key into the screen's event. ok is false when
// the message raises none. f is the frame the screen last returned.
func DownloadHandle(f Frame, msg tea.Msg) (DownloadEvent, bool) {
	switch m := msg.(type) {
	case tea.MouseClickMsg:
		if r, ok := f.eventAt(m.X, m.Y); ok {
			switch r.Event {
			case "PickPlaylist":
				return DownloadPickPlaylist{X: m.X - r.X, Y: m.Y - r.Y}, true
			case "PickEntry":
				return DownloadPickEntry{X: m.X - r.X, Y: m.Y - r.Y}, true
			case "Hint":
				return DownloadHint{X: m.X - r.X, Y: m.Y - r.Y}, true
			}
		}
	}
	_ = f
	return nil, false
}
